/** Native inventory emblems encode the item's actual effect, rather than a rarity color alone. */
export function supplyCanvas(item,size=72){const c=document.createElement('canvas');c.width=c.height=size;c.className='supply-emblem';c.setAttribute('aria-label',item.name);drawSupply(c.getContext('2d'),item,size);return c;}
export function drawSupply(c,item,size=72){c.save();c.scale(size/72,size/72);const e=item.effect,all=/All$/.test(e)||e==='rally',attack=/burn|slow|wet|shock|shatter|leech|blast|Siphon|interrupt|delay|dispel|mark|tide/.test(e),color=attack?'#dfae7f':/mp|strain|haste|rally/.test(e)?'#8ecadd':'#9dd4ae';const g=c.createLinearGradient(0,0,72,72);g.addColorStop(0,'#29444f');g.addColorStop(1,'#101f29');c.fillStyle=g;c.beginPath();c.roundRect(3,3,66,66,13);c.fill();c.strokeStyle=color+'88';c.lineWidth=1;c.stroke();c.translate(36,35);c.fillStyle=color;c.strokeStyle=color;c.lineWidth=2.5;c.lineCap='round';
 if(e==='rally'){c.beginPath();c.moveTo(-19,1);c.lineTo(15,-11);c.lineTo(15,12);c.closePath();c.fill();for(let i=0;i<3;i++){c.beginPath();c.arc(18,0,6+i*5,-.7,.7);c.stroke();}}
 else if(/revive/.test(e)){c.beginPath();c.moveTo(0,-20);c.bezierCurveTo(25,-3,17,14,0,20);c.bezierCurveTo(-17,14,-25,-3,0,-20);c.fill();c.fillStyle='#17303b';c.fillRect(-2,-8,4,22);c.fillRect(-9,0,18,4);}
 else if(/shield|guard|insulate|cool/i.test(e)){c.beginPath();c.moveTo(-18,-13);c.lineTo(0,-20);c.lineTo(18,-13);c.lineTo(13,10);c.lineTo(0,21);c.lineTo(-13,10);c.closePath();c.stroke();c.globalAlpha=.25;c.fill();c.globalAlpha=1;c.beginPath();c.moveTo(-7,0);c.lineTo(-1,6);c.lineTo(10,-8);c.stroke();}
 else if(/heal|cleanse|strain/.test(e)){c.beginPath();c.roundRect(-13,-13,26,31,7);c.stroke();c.fillRect(-9,-21,18,5);c.fillRect(-2,-7,4,19);c.fillRect(-9,0,18,4);}
 else if(/delay|haste/.test(e)){c.beginPath();c.arc(0,0,19,0,Math.PI*2);c.stroke();c.beginPath();c.moveTo(0,-12);c.lineTo(0,0);c.lineTo(e==='delayAll'?-10:10,6);c.stroke();}
 else if(/dispel|interrupt/.test(e)){c.beginPath();c.arc(0,2,16,Math.PI,Math.PI*2);c.lineTo(18,14);c.lineTo(-18,14);c.closePath();c.stroke();c.beginPath();c.moveTo(-22,18);c.lineTo(21,-21);c.stroke();}
 else if(/mp/.test(e)){c.beginPath();c.moveTo(0,-22);c.lineTo(15,-2);c.lineTo(0,21);c.lineTo(-15,-2);c.closePath();c.stroke();c.globalAlpha=.3;c.fill();c.globalAlpha=1;}
 else{c.beginPath();for(let n=0;n<10;n++){const a=n*Math.PI/5-Math.PI/2,r=n%2?9:22;n?c.lineTo(Math.cos(a)*r,Math.sin(a)*r):c.moveTo(Math.cos(a)*r,Math.sin(a)*r);}c.closePath();c.stroke();}
 if(all){c.fillStyle='#e4d5af';for(const x of [-9,0,9]){c.beginPath();c.arc(x,27,2,0,7);c.fill();}}c.restore();}
